import itertools
import json

def solve():
    houses = [1, 2]

    Names = ["Arnold", "Eric"]
    Educations = ["associate", "high school"]
    Heights = ["short", "very short"]
    Foods = ["grilled cheese", "pizza"]
    Drinks = ["tea", "water"]

    solutions = []

    for name_perm in itertools.permutations(Names):
        name = {houses[i]: name_perm[i] for i in range(len(houses))}
        for edu_perm in itertools.permutations(Educations):
            edu = {houses[i]: edu_perm[i] for i in range(len(houses))}
            for height_perm in itertools.permutations(Heights):
                height = {houses[i]: height_perm[i] for i in range(len(houses))}
                for food_perm in itertools.permutations(Foods):
                    food = {houses[i]: food_perm[i] for i in range(len(houses))}
                    # Clue 2: grilled cheese is in house 2
                    if food[2] != "grilled cheese":
                        continue
                    for drink_perm in itertools.permutations(Drinks):
                        drink = {houses[i]: drink_perm[i] for i in range(len(houses))}

                        ok = True
                        # Clue 1: very short == pizza
                        for h in houses:
                            if (height[h] == "very short") != (food[h] == "pizza"):
                                ok = False
                                break
                        if not ok:
                            continue

                        # Clue 3: high school == pizza
                        for h in houses:
                            if (edu[h] == "high school") != (food[h] == "pizza"):
                                ok = False
                                break
                        if not ok:
                            continue

                        # Clue 4: tea == grilled cheese
                        for h in houses:
                            if (drink[h] == "tea") != (food[h] == "grilled cheese"):
                                ok = False
                                break
                        if not ok:
                            continue

                        # Clue 5: Arnold == pizza
                        for h in houses:
                            if (name[h] == "Arnold") != (food[h] == "pizza"):
                                ok = False
                                break
                        if not ok:
                            continue

                        solutions.append({
                            "Name": name,
                            "Education": edu,
                            "Height": height,
                            "Food": food,
                            "Drink": drink
                        })

    if not solutions:
        raise RuntimeError("No solution found")

    # Take the first solution (should be unique)
    sol = solutions[0]
    header = ["House", "Name", "Education", "Height", "Food", "Drink"]
    rows = []
    for h in houses:
        rows.append([
            str(h),
            sol["Name"][h],
            sol["Education"][h],
            sol["Height"][h],
            sol["Food"][h],
            sol["Drink"][h],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    solve()
